```go
package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML
func Render(markdown string) string {
	lines := strings.Split(markdown, "\n")
	var html strings.Builder

	listOpen := false
	for _, line := range lines {
		if strings.HasPrefix(line, "* ") {
			if !listOpen {
				html.WriteString("<ul>")
				listOpen = true
			}
			html.WriteString("<li>" + line[2:] + "</li>")
			continue
		}
		if listOpen {
			html.WriteString("</ul>")
			listOpen = false
		}
		if n, ok := headerLevel(line); ok {
			html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", n, line[n+1:], n))
		} else {
			html.WriteString("<p>" + line + "</p>")
		}
	}
	if listOpen {
		html.WriteString("</ul>")
	}
	return html.String()
}

// headerLevel reports the header level if line starts with 1-6 '#' followed by a space
func headerLevel(line string) (int, bool) {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level >= 1 && level <= 6 && level < len(line) && line[level] == ' ' {
		return level, true
	}
	return 0, false
}
```

